/**
 * Loads `src/seo/*` into a Node script.
 *
 * The route table is TypeScript and imports the app's own data modules, so a
 * build script cannot `require` it and cannot `import` it either — Node does
 * not resolve extensionless TypeScript imports. esbuild ships with Vite and is
 * already in the tree, so the table is bundled to a temporary ESM file and
 * imported from there.
 *
 * The point of going to this trouble rather than copying the strings into the
 * scripts is that copying is how the sitemap, the static HTML and the running
 * app end up telling three different stories. There is one table; every
 * consumer reads it from here.
 */
import { build } from 'esbuild'
import { existsSync, rmSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))

/**
 * The project root — every script resolves its paths from here.
 *
 * Not simply `resolve(__dirname, '..', '..')`, because this module is also
 * imported by `vite.config.ts`, and Vite bundles a config into a temporary file
 * *in the project root* before running it. From there `import.meta.url` points
 * at the project root rather than at `scripts/lib`, and two levels up is
 * somebody else's directory. So the candidates are tried in order and the one
 * that actually contains the route table wins.
 */
export const root =
  [resolve(__dirname, '..', '..'), resolve(__dirname, '..'), process.cwd()].find((dir) =>
    existsSync(join(dir, 'src', 'seo', 'build.ts')),
  ) ?? process.cwd()

/**
 * Bundle and import the SEO entry point.
 *
 * The bundle is written inside the project rather than to the OS temp dir so
 * that anything esbuild leaves as a bare import still resolves against the
 * project's own node_modules.
 */
export async function loadSeo() {
  const outDir = resolve(root, 'node_modules', '.cache', 'xelvic-seo')
  const outfile = join(outDir, 'seo.mjs')

  await build({
    entryPoints: [resolve(root, 'src', 'seo', 'build.ts')],
    outfile,
    bundle: true,
    format: 'esm',
    platform: 'node',
    target: 'node20',
    /* The app's data modules import React and lucide-react for their icons.
       Nothing in the route table touches either at runtime — the icon fields
       are simply carried along — so they stay out of the bundle and resolve
       normally when the file is imported. */
    external: ['react', 'react-dom', 'lucide-react'],
    logLevel: 'warning',
    banner: {
      js: '/* Generated by scripts/lib/seo-bundle.mjs — do not edit. */',
    },
  })

  try {
    return await import(pathToFileURL(outfile).href)
  } finally {
    rmSync(outDir, { recursive: true, force: true })
  }
}
